WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SQLBLANKLINES ON
DECLARE
  n NUMBER;
BEGIN

  SELECT COUNT(*) INTO n FROM USER_OBJECTS WHERE OBJECT_TYPE NOT IN ('INDEX','LOB') AND STATUS <> 'VALID';
  IF n <> 0 THEN RAISE_APPLICATION_ERROR(-20101, 'Invalid schema objects'); END IF;
END;
/

DECLARE
  TYPE column_map IS TABLE OF VARCHAR2(1000) INDEX BY VARCHAR2(128);
  actual column_map;
  target_table VARCHAR2(128) := 'BKITEM';
BEGIN
  FOR c IN (SELECT COLUMN_NAME, DATA_TYPE, DATA_LENGTH, DATA_PRECISION, DATA_SCALE,
                   NULLABLE, CHAR_USED, CHAR_LENGTH FROM USER_TAB_COLUMNS
            WHERE TABLE_NAME=target_table) LOOP
    actual(c.COLUMN_NAME) := c.DATA_TYPE || '|' || c.NULLABLE || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DATA_TYPE='NUMBER' THEN NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') ELSE '-|-' END;
  END LOOP;
  IF actual.COUNT <> 4 THEN RAISE_APPLICATION_ERROR(-20102, 'Column count differs: BKITEM'); END IF;

  IF NOT actual.EXISTS('ID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: BKITEM.ID'); END IF;
  IF actual('ID') <> 'CLOB|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: BKITEM.ID'); END IF;

  IF NOT actual.EXISTS('ORDERCATEGORY') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: BKITEM.ORDERCATEGORY'); END IF;
  IF actual('ORDERCATEGORY') <> 'CLOB|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: BKITEM.ORDERCATEGORY'); END IF;

  IF NOT actual.EXISTS('TESTNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: BKITEM.TESTNAME'); END IF;
  IF actual('TESTNAME') <> 'CLOB|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: BKITEM.TESTNAME'); END IF;

  IF NOT actual.EXISTS('CREATEDBYORGNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: BKITEM.CREATEDBYORGNAME'); END IF;
  IF actual('CREATEDBYORGNAME') <> 'VARCHAR2|Y|270|B|270|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: BKITEM.CREATEDBYORGNAME'); END IF;

END;
/

