DECLARE
  TYPE column_map IS TABLE OF VARCHAR2(1000) INDEX BY VARCHAR2(128);
  actual column_map;
  target_table VARCHAR2(128) := 'QYREMARK';
BEGIN
  FOR c IN (SELECT COLUMN_NAME, DATA_TYPE, DATA_LENGTH, DATA_PRECISION, DATA_SCALE,
                   NULLABLE, CHAR_USED, CHAR_LENGTH FROM USER_TAB_COLUMNS
            WHERE TABLE_NAME=target_table) LOOP
    actual(c.COLUMN_NAME) := c.DATA_TYPE || '|' || c.NULLABLE || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DATA_TYPE='NUMBER' THEN NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') ELSE '-|-' END;
  END LOOP;
  IF actual.COUNT <> 3 THEN RAISE_APPLICATION_ERROR(-20102, 'Column count differs: QYREMARK'); END IF;

  IF NOT actual.EXISTS('QYNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: QYREMARK.QYNAME'); END IF;
  IF actual('QYNAME') <> 'CLOB|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: QYREMARK.QYNAME'); END IF;

  IF NOT actual.EXISTS('REMARK') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: QYREMARK.REMARK'); END IF;
  IF actual('REMARK') <> 'CLOB|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: QYREMARK.REMARK'); END IF;

  IF NOT actual.EXISTS('CREATEDBYORGNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: QYREMARK.CREATEDBYORGNAME'); END IF;
  IF actual('CREATEDBYORGNAME') <> 'VARCHAR2|Y|270|B|270|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: QYREMARK.CREATEDBYORGNAME'); END IF;

END;
/

