  IF actual('ANCESTOR_OBJECT_SCHEMA') <> 'VARCHAR2|Y|128|B|128|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: SYS_IMPORT_FULL_02.ANCESTOR_OBJECT_SCHEMA'); END IF;

  IF NOT actual.EXISTS('ANCESTOR_OBJECT_TYPE') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: SYS_IMPORT_FULL_02.ANCESTOR_OBJECT_TYPE'); END IF;
  IF actual('ANCESTOR_OBJECT_TYPE') <> 'VARCHAR2|Y|128|B|128|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: SYS_IMPORT_FULL_02.ANCESTOR_OBJECT_TYPE'); END IF;

  IF NOT actual.EXISTS('ANCESTOR_PROCESS_ORDER') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: SYS_IMPORT_FULL_02.ANCESTOR_PROCESS_ORDER'); END IF;
  IF actual('ANCESTOR_PROCESS_ORDER') <> 'NUMBER|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: SYS_IMPORT_FULL_02.ANCESTOR_PROCESS_ORDER'); END IF;

