DECLARE
  TYPE column_map IS TABLE OF VARCHAR2(1000) INDEX BY VARCHAR2(128);
  actual column_map;
  target_table VARCHAR2(128) := 'T_EMC_INFO_DATA_ITEM';
BEGIN
  FOR c IN (SELECT COLUMN_NAME, DATA_TYPE, DATA_LENGTH, DATA_PRECISION, DATA_SCALE,
                   NULLABLE, CHAR_USED, CHAR_LENGTH FROM USER_TAB_COLUMNS
            WHERE TABLE_NAME=target_table) LOOP
    actual(c.COLUMN_NAME) := c.DATA_TYPE || '|' || c.NULLABLE || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DATA_TYPE='NUMBER' THEN NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') ELSE '-|-' END;
  END LOOP;
  IF actual.COUNT <> 12 THEN RAISE_APPLICATION_ERROR(-20102, 'Column count differs: T_EMC_INFO_DATA_ITEM'); END IF;

  IF NOT actual.EXISTS('ID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.ID'); END IF;
  IF actual('ID') <> 'NUMBER|N|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.ID'); END IF;

  IF NOT actual.EXISTS('INFOCONFIGID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.INFOCONFIGID'); END IF;
  IF actual('INFOCONFIGID') <> 'NUMBER|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.INFOCONFIGID'); END IF;

  IF NOT actual.EXISTS('INFODATAID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.INFODATAID'); END IF;
