  IF NOT actual.EXISTS('MONITORPOINTNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.MONITORPOINTNAME'); END IF;
  IF actual('MONITORPOINTNAME') <> 'VARCHAR2|Y|120|B|120|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.MONITORPOINTNAME'); END IF;

  IF NOT actual.EXISTS('ITEMNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.ITEMNAME'); END IF;
  IF actual('ITEMNAME') <> 'VARCHAR2|Y|120|B|120|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.ITEMNAME'); END IF;

  IF NOT actual.EXISTS('RESULT') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.RESULT'); END IF;
  IF actual('RESULT') <> 'VARCHAR2|Y|60|B|60|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.RESULT'); END IF;

  IF NOT actual.EXISTS('MONITORDATE') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.MONITORDATE'); END IF;
  IF actual('MONITORDATE') <> 'DATE|Y|-|-|-|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.MONITORDATE'); END IF;

  IF NOT actual.EXISTS('CREATEDBYID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.CREATEDBYID'); END IF;
  IF actual('CREATEDBYID') <> 'VARCHAR2|Y|36|B|36|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.CREATEDBYID'); END IF;

  IF NOT actual.EXISTS('CREATEDBYNAME') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: T_EMC_INFO_DATA_ITEM.CREATEDBYNAME'); END IF;
  IF actual('CREATEDBYNAME') <> 'VARCHAR2|Y|60|B|60|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: T_EMC_INFO_DATA_ITEM.CREATEDBYNAME'); END IF;

