DECLARE
  TYPE column_map IS TABLE OF VARCHAR2(1000) INDEX BY VARCHAR2(128);
  actual column_map;
  target_table VARCHAR2(128) := 'test';
BEGIN
  FOR c IN (SELECT COLUMN_NAME, DATA_TYPE, DATA_LENGTH, DATA_PRECISION, DATA_SCALE,
                   NULLABLE, CHAR_USED, CHAR_LENGTH FROM USER_TAB_COLUMNS
            WHERE TABLE_NAME=target_table) LOOP
    actual(c.COLUMN_NAME) := c.DATA_TYPE || '|' || c.NULLABLE || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DATA_TYPE='NUMBER' THEN NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') ELSE '-|-' END;
  END LOOP;
  IF actual.COUNT <> 3 THEN RAISE_APPLICATION_ERROR(-20102, 'Column count differs: test'); END IF;

  IF NOT actual.EXISTS('EQUIPTID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: test.EQUIPTID'); END IF;
  IF actual('EQUIPTID') <> 'VARCHAR2|Y|100|B|100|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: test.EQUIPTID'); END IF;

  IF NOT actual.EXISTS('ZICHANID') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: test.ZICHANID'); END IF;
  IF actual('ZICHANID') <> 'VARCHAR2|Y|100|B|100|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: test.ZICHANID'); END IF;

  IF NOT actual.EXISTS('ZICHANNO') THEN RAISE_APPLICATION_ERROR(-20103, 'Missing column: test.ZICHANNO'); END IF;
  IF actual('ZICHANNO') <> 'VARCHAR2|Y|100|B|100|-|-' THEN RAISE_APPLICATION_ERROR(-20103, 'Column differs: test.ZICHANNO'); END IF;

END;
