DECLARE
  TYPE signature_counts IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(4000);
  actual signature_counts;
  signature VARCHAR2(4000);
BEGIN
  FOR c IN (SELECT c.TABLE_NAME, c.CONSTRAINT_TYPE, c.STATUS, c.VALIDATED,
                   LISTAGG(cc.COLUMN_NAME, '|') WITHIN GROUP (ORDER BY cc.POSITION) AS COLUMN_NAMES
            FROM USER_CONSTRAINTS c JOIN USER_CONS_COLUMNS cc ON cc.CONSTRAINT_NAME=c.CONSTRAINT_NAME
            WHERE c.CONSTRAINT_TYPE IN ('P','U')
            GROUP BY c.CONSTRAINT_NAME, c.TABLE_NAME, c.CONSTRAINT_TYPE, c.STATUS, c.VALIDATED) LOOP
    signature := c.TABLE_NAME || '|' || c.CONSTRAINT_TYPE || '|' || c.STATUS || '|' || c.VALIDATED || '|' || c.COLUMN_NAMES;
    IF actual.EXISTS(signature) THEN actual(signature) := actual(signature)+1; ELSE actual(signature) := 1; END IF;
  END LOOP;

