DECLARE
  TYPE index_map IS TABLE OF VARCHAR2(4000) INDEX BY VARCHAR2(128);
  actual index_map;
BEGIN
  FOR i IN (SELECT i.INDEX_NAME, i.TABLE_NAME, i.INDEX_TYPE, i.UNIQUENESS, i.STATUS,
                   LISTAGG(ic.COLUMN_NAME || ':' || ic.DESCEND, '|') WITHIN GROUP (ORDER BY ic.COLUMN_POSITION) AS COLUMN_NAMES
            FROM USER_INDEXES i JOIN USER_IND_COLUMNS ic ON ic.INDEX_NAME=i.INDEX_NAME
            WHERE i.INDEX_TYPE='NORMAL'
            GROUP BY i.INDEX_NAME, i.TABLE_NAME, i.INDEX_TYPE, i.UNIQUENESS, i.STATUS) LOOP
    actual(i.INDEX_NAME) := i.TABLE_NAME || '|' || i.INDEX_TYPE || '|' || i.UNIQUENESS || '|' || i.STATUS || '|' || i.COLUMN_NAMES;
  END LOOP;

